FQN: Example: List mailbox names from a canned response
Kind: verified_example
Provenance: authored
Verification: passed
Authored example: written for foss-mcp against the pinned library, not taken from the upstream README; published only after the ingestion verifier compiled or ran it against that commit.
Uses the same kind of in-memory IJmapTransport and calls ListMailboxesAsync with an account id; prints the Name of each Mailbox it returns.

Example:
// Authored example: list mailbox names with ListMailboxesAsync against canned JMAP responses
using System;
using System.Collections.Generic;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Aspose.Jmap;

var options = new JmapClientOptions
{
    SessionUrl = new Uri("https://jmap.example.invalid/.well-known/jmap"),
    Username = "user@example.invalid",
    Password = "placeholder",
    Transport = new CannedMailTransport(),
};

using var client = new JmapClient(options);
await client.ConnectAsync();

string accountId = "A1";
IReadOnlyList<Mailbox> mailboxes = await client.ListMailboxesAsync(accountId);

foreach (var mailbox in mailboxes)
{
    Console.WriteLine(mailbox.Name);
}

class CannedMailTransport : IJmapTransport
{
    private const string SessionJson = """
        {
          "capabilities": { "urn:ietf:params:jmap:core": {} },
          "accounts": { "A1": { "name": "user@example.invalid", "isPersonal": true } },
          "primaryAccounts": { "urn:ietf:params:jmap:mail": "A1" },
          "username": "user@example.invalid",
          "apiUrl": "https://jmap.example.invalid/api",
          "downloadUrl": "https://jmap.example.invalid/download/{accountId}/{blobId}/{name}",
          "uploadUrl": "https://jmap.example.invalid/upload/{accountId}",
          "eventSourceUrl": "https://jmap.example.invalid/events",
          "state": "s1"
        }
        """;

    private const string MailboxGetJson = """
        {
          "sessionState": "s1",
          "methodResponses": [
            ["Mailbox/get", {
              "accountId": "A1",
              "state": "m1",
              "list": [
                { "id": "mb1", "name": "Inbox", "role": "inbox" },
                { "id": "mb2", "name": "Archive" }
              ],
              "notFound": []
            }, "c1"]
          ]
        }
        """;

    public Task<JmapHttpResponse> SendAsync(JmapHttpRequest request, CancellationToken cancellationToken = default)
    {
        string body = request.Method == "GET" ? SessionJson : MailboxGetJson;
        var response = new JmapHttpResponse { StatusCode = 200, Body = Encoding.UTF8.GetBytes(body) };
        return Task.FromResult(response);
    }
}
