// Authored example: build a JMAP request envelope for Mailbox/get and print its JSON
using System;
using System.Collections.Generic;
using System.Text.Json;
using Aspose.Jmap;

var getMailboxes = new Invocation
{
    Name = "Mailbox/get",
    Arguments = new Dictionary<string, object> { ["accountId"] = "A1" },
    MethodCallId = "c1",
};

var envelope = new JmapRequestEnvelope
{
    Using = new[] { "urn:ietf:params:jmap:core", "urn:ietf:params:jmap:mail" },
    MethodCalls = new[] { getMailboxes },
};

Console.WriteLine(JsonSerializer.Serialize(envelope));
